using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceOnHandBasedPreviewDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PreviewDescription/Any/DiceOnHandBasedPreviewDescription", order = 0)]
public class DiceOnHandBasedPreviewDescription : PreviewDescription
{
	public override int GetPreviewAmount(string amountModified, BattleAction battleAction)
	{
		return (battleAction as DiceOnHandBasedPurifyAction).GetPurifyAmount(GetAmountWithoutEquation(amountModified));
	}
}
